                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("explicit-fourier-residual-integrable"),
                DeclarationHandle.Create("D5/S3/Weil/Mertens/IntegratedExplicit/WholeFormula.explicitFourierResidual_integrable"),
